pub struct Solution;

impl Solution {
    pub fn max_sum(nums: Vec<i32>, k: i32) -> i32 {
        let m = 1_000_000_007;
        let mut bits = vec![0_usize; 30];
        for mut n in nums.into_iter() {
            let mut position = 0_usize;
            while n != 0 {
                let digit = n % 2;
                if digit != 0 {
                    bits[position] += 1;
                }
                position += 1;
                n >>= 1;
            }
        }
        let mut sum = 0;
        for _ in 0..k {
            let mut n = 0_i64;
            for (i, c) in bits.iter_mut().enumerate() {
                if *c > 0 {
                    *c -= 1;
                    n += 1 << i;
                }
            }
            sum = (sum + (n.pow(2) % m)) % m;
        }
        sum as i32
    }
}

